/*
 * A210879  Triangle of coefficients of polynomials v(n,x) jointly generated
 *          with A210878; see the Formula section.
 * https://oeis.org/A210879
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) is the coefficient of x^(k-1) in the polynomial v(k,x),
 *            where k is chosen so that k*(k-1)/2 < n ≤ k*(k+1)/2. The
 *            polynomials u(n,x) and v(n,x) are generated by u(n,x) =
 *            x*u(n-1,x) + 2x*v(n-1,x), v(n,x) = (x+1)*u(n-1,x) + x*v(n-1,x) +
 *            1, with initial values u(1,x)=1, v(1,x)=1. The triangle of...
 * Range:     u8 n <= 25, u16 n <= 62, u32 n <= 62, u64 n <= 62, u128 n <= 62,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Compile with -std=c11 or -std=c++17; seq_t and idx_t are provided by the build. */
#include <stddef.h>
#define MAX_ROW 20000   /* enough for n up to ~10 000 */

seq_t a(idx_t n)
{
    /* Special case: the offset is 1. */
    if (n == 0) return (seq_t)0;   /* undefined, return 0 */

    /* Polynomial coefficient arrays.  We keep two copies for the
       current and the next row to avoid overwriting data needed
       during the update. */
    static seq_t u_cur[MAX_ROW];
    static seq_t v_cur[MAX_ROW];
    static seq_t u_next[MAX_ROW];
    static seq_t v_next[MAX_ROW];
    seq_t *p_u_cur = u_cur;
    seq_t *p_v_cur = v_cur;
    seq_t *p_u_next = u_next;
    seq_t *p_v_next = v_next;

    /* Initialize the first row (n = 1). */
    for (int i = 0; i < MAX_ROW; ++i) {
        p_u_cur[i] = 0;
        p_v_cur[i] = 0;
    }
    p_u_cur[0] = 1;     /* u(1,x) = 1   */
    p_v_cur[0] = 1;     /* v(1,x) = 1   */

    if (n == 1) return p_v_cur[0];

    /* Position counter for the flattened triangle. */
    idx_t pos = 1;   /* we have already counted the first coefficient */

    for (int r = 2; ; ++r) {
        int prev_deg  = r - 2;   /* degree of the previous row   */
        int next_deg  = r - 1;   /* degree of the current row    */

        /* Zero the next-row arrays up to the required degree. */
        for (int i = 0; i <= next_deg; ++i) {
            p_u_next[i] = 0;
            p_v_next[i] = 0;
        }

        /* Compute u(r,x).  u_next[i+1] = u_cur[i] + 2*v_cur[i]. */
        for (int i = 0; i <= prev_deg; ++i) {
            p_u_next[i + 1] = p_u_cur[i] + (seq_t)2 * p_v_cur[i];
        }

        /* Compute v(r,x).
           v_next[i]   += u_cur[i];
           v_next[i+1] += u_cur[i] + v_cur[i];   */
        for (int i = 0; i <= prev_deg; ++i) {
            p_v_next[i]   += p_u_cur[i];
            p_v_next[i+1] += p_u_cur[i];
            p_v_next[i+1] += p_v_cur[i];
        }
        /* Add the constant term +1. */
        p_v_next[0] += 1;

        /* Scan the coefficients of v(r,x). Each coefficient occupies
           one position in the flattened sequence. */
        for (int i = 0; i <= next_deg; ++i) {
            ++pos;
            if (pos == n) return p_v_next[i];
        }

        /* Prepare for the next iteration: make the new row the current one. */
        seq_t *tmp_u = p_u_cur;
        p_u_cur = p_u_next;
        p_u_next = tmp_u;
        seq_t *tmp_v = p_v_cur;
        p_v_cur = p_v_next;
        p_v_next = tmp_v;
    }
}
